import json, subprocess, os, sys
def call(name, args=None):
    payload=json.dumps({"name":name,"arguments":args or {}})
    out=subprocess.run(["ft2","call",name,json.dumps(args or {},separators=(',',':'))],capture_output=True,text=True)
    return _parse(out)
def _parse(out):
    txt=out.stdout.strip()
    try:
        j=json.loads(txt)
        c=j.get("content",[{}])[0].get("text","")
        if j.get("isError"):
            print("ERR:",txt,file=sys.stderr)
        try:
            return json.loads(c)
        except Exception:
            return c
    except Exception:
        print("BADOUT:",txt,out.stderr,file=sys.stderr)
        raise
def batch(calls, tmp="/tmp/batch.json"):
    with open(tmp,"w") as f:
        json.dump([{"name":n,"arguments":a} for n,a in calls],f)
    out=subprocess.run(["ft2","batch",tmp],capture_output=True,text=True)
    return out.stdout, out.stderr
def rows(cells):
    return cells
