import sys; sys.path.insert(0,'src')
import numpy as np
from ft2 import call
SR=44100
ROOTS={'bass':45,'lead':69,'pluck':84,'pad':64,'blip':81,'kick':0,'snare':0,'hatc':0,'hato':0,'tom':0,'riser':0}
BPM=150; SPD=6
def byte(midi,root): return max(1,min(96,int(round(midi-root))+77))
cells={}
def note(pat,row,ch,midi,inst,vol=None,root=0,eff=0,dp=0):
    b=byte(midi,root) if midi else 0
    if vol is None: vol=64
    cells[(pat,row,ch)]=(b,inst,vol,eff,dp)
# ---- instrument numbers
INSTS=['kick','bass','lead','pluck','pad','snare','hatc','hato','tom','blip','riser']
num={}
for i,nm in enumerate(INSTS):
    num[nm]=i+1
    call("sample_load",{"path":f"/workspace/samples/{nm}.wav","instrument":i+1,"sample":0})
    call("sample_set",{"instrument":i+1,"sample":0,"relative_note":0,"panning":128,"volume":64,"name":nm})
    call("instrument_set",{"instrument":i+1,"name":nm.capitalize()})
K,B,L,P,D,S,HC,HO,T,BL,R = (num['kick'],num['bass'],num['lead'],num['pluck'],num['pad'],num['snare'],num['hatc'],num['hato'],num['tom'],num['blip'],num['riser'])
RK=ROOTS['bass']; RL=ROOTS['lead']; RP=ROOTS['pluck']; RD=ROOTS['pad']; RB=ROOTS['blip']
# chord progression (Am F C G) - 4 bars each pattern section
# bass roots in midi
BR=[45,41,36,43]
# ---------- PATTERNS: each 64 rows ----------
NPAT=5
for p in range(NPAT): call("pattern_set_length",{"pattern":p,"rows":64})
def drums(p, style=0):
    for bar in range(4):
        b0=bar*16
        # kick on 1 and 3(&) ; snare on 2,4; hats on 8ths
        note(p,b0+0,4,0,K,48,root=0)
        if style>=1: note(p,b0+6,4,0,K,42,root=0)
        if style==2: note(p,b0+10,4,0,K,40,root=0)
        note(p,b0+8,5,0,S,44,root=0)
        for e in range(8):
            note(p,b0+e*2,6,0,HC,28 if e%2 else 36,root=0)
        if style>=2:
            note(p,b0+14,7,0,T,34,root=0)
def bassline(p, octave_up=False, gate=6):
    for bar in range(4):
        r=BR[bar]; b0=bar*16
        pat=[0,0,12,0,7,0,12,0,0,12,7,0,12,7,0,7] if not octave_up else [0,12,0,12,7,12,0,12,0,12,7,12,12,7,12,7]
        for i,iv in enumerate(pat):
            if iv is None: continue
            note(p,b0+i*4,2,r+iv,B,52,root=RK)
def arp(p, roots, div=4):
    for bar in range(4):
        b0=bar*16
        tones=roots[bar]
        for i in range(16//div):
            m=b0+i*div
            t=tones[i%len(tones)]
            note(m and p or p, m, 3, t, P, 40, root=RP)
ARPS=[[69,72,76,81],[65,69,72,77],[64,67,72,76],[67,71,76,79]]
def pads(p, sus=64):
    for bar in range(4):
        b0=bar*16
        ch=[57,53,48,55][bar]
        note(p,b0,6,ch,D,sus,root=RD)
# ---- P0 intro: pads + arp + riser
pads(0); arp(0)
note(0,48,7,0,R,40,root=0)
for i,t in enumerate([81,84,88]): note(0,56+i*2,7,t,BL,40,root=RB)
# ---- P1 main theme A
drums(1,1); bassline(1); pads(1,40)
THEME=[(0,76,8),(8,72,4),(12,74,4),(16,76,8),(24,79,8),(32,76,4),(36,74,4),(40,72,8),(48,69,12),(60,72,4)]
for m,t,d in THEME: note(1,m,0,t,L,58,root=RL)
# ---- P2 theme B (higher)
drums(2,2); bassline(2,True); pads(2,40)
T2=[(0,81,6),(6,79,2),(8,76,8),(16,77,6),(22,79,2),(24,81,8),(32,84,12),(44,83,4),(48,81,8),(56,79,8)]
for m,t,d in T2: note(2,m,0,t,L,60,root=RL)
for m,t,d in [(4,72,4),(12,76,4),(20,72,4),(28,77,4),(36,76,4),(44,72,4),(52,76,4),(60,79,4)]:
    note(2,m,1,t,L,38,root=RL)
# ---- P3 breakdown: arp + pad only + tom fills
pads(3,52); arp(3, div=2)
for i,t in enumerate([76,79,84,79]): note(3,48+i*4,0,t,L,48,root=RL)
for r in range(0,64,8): note(3,r,4,0,K,44,root=0)
for r in range(56,64,2): note(3,r,7,0,T,40,root=0)
# ---- P4 finale: theme A up an octave, full drums
drums(4,2); bassline(4,True); pads(4,44)
for m,t,d in THEME: note(4,m,0,t+12,L,62,root=RL)
for m,t,d in [(2,72,4),(10,76,4),(18,79,4),(26,84,4),(34,76,4),(42,81,4),(50,84,4),(58,88,4)]:
    note(4,m,1,t,L,40,root=RL)
    note(4,m,3,t,RP and P,34,root=RP)
for p in range(NPAT):
    for (pp,r,c),v in list(cells.items()):
        if pp==p: pass
call("song_set",{"length":8,"bpm":BPM,"speed":SPD,"loop_start":1})
ORDER=[0,1,2,1,3,2,4,4]
for i,o in enumerate(ORDER): call("order_set",{"position":i,"pattern":o})
# write cells
for (p,r,c),(b,ins,vol,eff,dp) in cells.items():
    call("pattern_set_cell",{"pattern":p,"row":r,"channel":c,"note":b,"instrument":ins,"volume":vol,"effect":eff,"effect_param":dp})
call("module_new",{"channels":8,"name":"Neon Circuit"})
PYEOF
